css:
.fx-tv{width:min(900px,100%);display:grid;gap:2.4em;padding:1em 0 6vh}
.fx-tv h2{font-size:clamp(1.8em,4vw,2.6em);text-align:center}
.fx-tv ol{position:relative;list-style:none;margin:0;padding:0;display:grid;gap:2.6em}
.fx-tv ol::before,.fx-tv ol::after{content:"";position:absolute;left:50%;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--border)}
.fx-tv ol::after{bottom:auto;height:var(--prog,100%);background:linear-gradient(var(--primary),var(--accent))}
.fx-tv li{display:grid;grid-template-columns:1fr 3.4em 1fr;align-items:start}
.fx-tv .dot{grid-column:2;grid-row:1;justify-self:center;margin-top:.45em;width:1.1em;height:1.1em;border-radius:50%;background:var(--surface);border:2px solid var(--accent);z-index:1;transition:background calc(.4s/var(--speed)),transform calc(.4s/var(--speed))}
.fx-tv .c{grid-row:1;grid-column:1;text-align:right;display:grid;gap:.35em;padding:1.1em 1.3em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-tv li:nth-child(even) .c{grid-column:3;text-align:left}
.fx-tv time{font:700 .8em var(--font-body);letter-spacing:.14em;color:var(--accent)}
.fx-tv h3{font-size:1.2em}.fx-tv .c p{opacity:.7;font-size:.94em}
.fx-tv.rdy li{opacity:0;transform:translateY(24px);transition:opacity calc(.7s/var(--speed)),transform calc(.7s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-tv.rdy li.in{opacity:1;transform:none}
.fx-tv.rdy li.in .dot{background:var(--accent);transform:scale(1.15)}
@media(max-width:640px){.fx-tv ol::before,.fx-tv ol::after{left:1.1em}.fx-tv li{grid-template-columns:2.2em 1fr}
.fx-tv .dot{grid-column:1;grid-row:1}.fx-tv .c,.fx-tv li:nth-child(even) .c{grid-column:2;text-align:left}}
@media(prefers-reduced-motion:reduce){.fx-tv.rdy li{opacity:1;transform:none;transition:none}.fx-tv .dot{transition:none}}
